/* Draws one glyph scaled by `scale` in both dimensions. For each
 * source pixel, draws a scale x scale block of screen pixels - this
 * is nearest-neighbor upscaling (not smoothed/interpolated), which
 * is the correct choice for bitmap fonts: smoothing a 1-bit font
 * produces blurry anti-aliasing artifacts, whereas blocky upscaling
 * keeps every glyph edge crisp, matching how bitmap fonts have
 * always been scaled in real terminal emulators and old VGA text
 * modes at higher resolutions. */
void font_draw_glyph(uint32_t x, uint32_t y, char c, color_t fg, color_t bg,
                     int bg_transparent, uint32_t scale) {
    if (scale == 0) scale = 1;

    uint8_t code = (uint8_t)c;
    const uint8_t *rows = font8x16_data[code];

    for (uint32_t row = 0; row < FONT8X16_HEIGHT; row++) {
        uint8_t bits = rows[row];
        for (uint32_t col = 0; col < FONT8X16_WIDTH; col++) {
            /* MSB = leftmost pixel - see header comment and the
             * verified round-trip check this was validated against. */
            int set = (bits >> (7 - col)) & 1;

            if (!set && bg_transparent) continue;

            color_t px_color = set ? fg : bg;

            uint32_t dst_x = x + col * scale;
            uint32_t dst_y = y + row * scale;

            for (uint32_t sy = 0; sy < scale; sy++) {
                graphics_fill_span(dst_x, dst_y + sy, scale, px_color);
            }
        }
    }
}
